{
  "code": "export default async function ({ page }) {
  const EMAIL = 'jessicamendesbarbosa5@gmail.com';
  const SENHA = 'amovoced28';
  const w = (ms) => new Promise(r => setTimeout(r, ms));
  const t = [];
  const mark = (label) => t.push(label + ':' + Math.round((Date.now() - start)/1000) + 's');
  const start = Date.now();
  try {
    await page.setViewport({ width: 1280, height: 800 });
    mark('viewport');
    await page.goto('https://app.cotadorsimplificado.com.br/login', { waitUntil: 'networkidle2', timeout: 20000 });
    mark('goto');
    const eInp = await page.$('#email_principal');
    if (eInp) { await eInp.click(); await eInp.type(EMAIL, { delay: 10 }); }
    mark('email');
    await page.evaluate(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.includes('Continuar com Email')); if(b) b.click(); });
    mark('btnCont');
    await page.waitForSelector('#pwdInput', { timeout: 8000 });
    mark('waitPwd');
    const sInp = await page.$('#pwdInput');
    if (sInp) { await sInp.click(); await sInp.type(SENHA, { delay: 10 }); }
    mark('senha');
    await page.evaluate(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim() === 'Entrar'); if(b) b.click(); });
    mark('btnEntr');
    await w(2500);
    mark('waitLogin');
    const url = page.url();
    mark('url');
    return { success: true, timing: t.join(' | '), url, total: Math.round((Date.now() - start)/1000) + 's' };
  } catch (error) { return { success: false, error: error.message, timing: t.join(' | '), total: Math.round((Date.now() - start)/1000) + 's' }; }
}"
}
